(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.035-t*0.5)*8+Math.cos((y+w1y)*0.025+t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.03+t*0.45)*8+Math.sin((x+w1x)*0.028-t*0.55)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.7+3)*110, 40+Math.cos(t*0.3+5)*60, 0.055, 2.8, 1.05],
    [400+Math.cos(t*0.45+2)*100, 200+Math.sin(t*0.65+4)*70, 0.11, 1.6, 0.85]
  ];
  let aS=0, iS=0, mS=0;
  for(const [sX,sY,f,sp,w] of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wv = Math.sin(d*f-t*sp);
    aS += wv*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    mS += Math.sin(d*f*1.4-t*sp*0.4+3.0)*w*0.5;
  }
  const n=src.length, act=aS/n, inh=iS/n, mod=mS/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=Math.sin(dist*0.08+ang*6+t*0.9)*Math.cos(dist*0.06-ang*5-t*1.3)*0.25;
  const turb=Math.sin(sx*0.09+Math.sin(sy*0.07+t)*2+t*1.5)*Math.cos(sy*0.08+Math.cos(sx*0.06-t)*2-t*1.2)*0.3;
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const rd2=Math.tanh((act*0.8+mod-inh*0.5+spiral2+turb)*1.8);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(sx*0.4+t*3)*Math.sin(sy*0.35-t*2.5)*0.08;
  const blend=rd1*0.45+rd2*0.25+cell*0.2+micro, v=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,42,88],[18,78,108],[24,128,122],[60,168,115],
    [180,188,70],[220,155,55],[215,100,60],[185,60,72],[130,35,68],
    [75,22,58],[30,14,48],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const c0=pal[i], c1=pal[i+1];
  const lum=0.75+Math.sin((rd1+rd2*0.5)*Math.PI)*0.25;
  const edge=Math.abs(rd1)>0.65?1.12:Math.abs(rd2)>0.7?1.08:1.0;
  const glow=Math.max(0, 1.0-Math.abs(rd1)*1.5)*0.15;
  const br=0.92+glow;
  return [
    Math.min(255, ((c0[0]+(c1[0]-c0[0])*f)*lum*edge*br+glow*40)|0),
    Math.min(255, ((c0[1]+(c1[1]-c0[1])*f)*lum*edge*br+glow*25)|0),
    Math.min(255, ((c0[2]+(c1[2]-c0[2])*f)*lum*edge*br+glow*15)|0)
  ];
}
